{"id":"ed8d59e6-ec6d-4d9a-b55c-86720823c75a","inserted_at":"2026-04-14T16:34:52.092+00:00","updated_at":"2026-04-14T16:34:52.092+00:00","type":"sql","name":"POI VAT Extension, Receipt Hashing, and Location Pings","description":"","content":{"sql":"-- =========================================================================\r\n-- L.O.T.O. HUB - Migration V4: Triangolo della Verità (ULTRA-RESILIENT VERSION)\r\n-- =========================================================================\r\n\r\n-- 0. RIPRISTINO BASELINE (Assicura che le colonne vitali esistano)\r\nALTER TABLE profiles ADD COLUMN IF NOT EXISTS nickname TEXT;\r\nALTER TABLE profiles ADD COLUMN IF NOT EXISTS onboarding_completed BOOLEAN DEFAULT false;\r\nALTER TABLE profiles ADD COLUMN IF NOT EXISTS is_cruise BOOLEAN DEFAULT false;\r\nALTER TABLE profiles ADD COLUMN IF NOT EXISTS has_accessibility_needs BOOLEAN DEFAULT false;\r\n\r\n-- 1. Estensione POIS con Partita IVA\r\nALTER TABLE pois ADD COLUMN IF NOT EXISTS p_iva TEXT;\r\n\r\n-- Popolazione P.IVA per i partner esistenti\r\nUPDATE pois SET p_iva = '01234567890' WHERE name = 'Museo Diocesano MuDi';\r\nUPDATE pois SET p_iva = '09876543210' WHERE name = 'Canneto Beach';\r\nUPDATE pois SET p_iva = '13579246801' WHERE name = 'Fatamorgana';\r\nUPDATE pois SET p_iva = '24680135790' WHERE name = 'Valle Rita';\r\n\r\n-- 2. Estensione IMPACT_TRANSACTIONS per Anti-Double-Spend\r\nALTER TABLE impact_transactions ADD COLUMN IF NOT EXISTS receipt_hash TEXT;\r\n\r\n-- Blocco di controllo per il vincolo UNIQUE (per evitare l'errore 42P07)\r\nDO $$ \r\nBEGIN \r\n    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'unique_receipt_hash') THEN\r\n        ALTER TABLE impact_transactions ADD CONSTRAINT unique_receipt_hash UNIQUE (receipt_hash);\r\n    END IF;\r\nEND $$;\r\n\r\n-- 3. Creazione Tabella LOCATION_PINGS (Eccezione Segnale Debole)\r\nCREATE TABLE IF NOT EXISTS location_pings (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    profile_id UUID REFERENCES profiles(id) ON DELETE CASCADE,\r\n    poi_id UUID REFERENCES pois(id) ON DELETE CASCADE,\r\n    coords GEOGRAPHY(POINT, 4326) NOT NULL,\r\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT now()\r\n);\r\n\r\n-- Indice per query spaziali e temporali (pings ultimi 12h)\r\nCREATE INDEX IF NOT EXISTS location_pings_time_idx ON location_pings(created_at);\r\nCREATE INDEX IF NOT EXISTS location_pings_profile_poi_idx ON location_pings(profile_id, poi_id);\r\n\r\n-- 4. Aggiornamento RPC: get_pois() per includere p_iva\r\nCREATE OR REPLACE FUNCTION get_pois()\r\nRETURNS TABLE (\r\n    id UUID,\r\n    name TEXT,\r\n    category TEXT,\r\n    layer_name TEXT,\r\n    xp_reward INTEGER,\r\n    checkin_radius INTEGER,\r\n    p_iva TEXT,\r\n    latitude FLOAT8,\r\n    longitude FLOAT8\r\n) AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    SELECT \r\n        p.id, \r\n        p.name, \r\n        p.category, \r\n        p.layer_name, \r\n        p.xp_reward, \r\n        p.checkin_radius,\r\n        p.p_iva,\r\n        ST_Y(p.coords::geometry) as latitude,\r\n        ST_X(p.coords::geometry) as longitude\r\n    FROM pois p\r\n    WHERE p.is_active = true;\r\nEND;\r\n$$ LANGUAGE plpgsql SECURITY DEFINER;\r\n\r\nCOMMENT ON FUNCTION get_pois() IS 'Restituisce i POI attivi includendo la P.IVA per la validazione del Triangolo della Verità.';\r\n","content_id":"ed8d59e6-ec6d-4d9a-b55c-86720823c75a","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
